CREATE TABLE services (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, api_key_hash CHAR(64) NOT NULL UNIQUE, webhook_url VARCHAR(500) NULL, webhook_secret_hash CHAR(64) NULL, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE customers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, email VARCHAR(190) NOT NULL, cpf_cnpj VARCHAR(20) NULL, phone VARCHAR(30) NULL, asaas_customer_id VARCHAR(80) NULL UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(email)) ENGINE=InnoDB;
CREATE TABLE products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, description TEXT NULL, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE plans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, name VARCHAR(160) NOT NULL, amount_cents INT UNSIGNED NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'BRL', cycle ENUM('ONE_TIME','WEEKLY','MONTHLY','BIMONTHLY','QUARTERLY','SEMIANNUALLY','YEARLY') NOT NULL DEFAULT 'ONE_TIME', active TINYINT(1) NOT NULL DEFAULT 1, FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
CREATE TABLE payment_links (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, token_hash CHAR(64) NOT NULL UNIQUE, product_id BIGINT UNSIGNED NULL, plan_id BIGINT UNSIGNED NULL, customer_id BIGINT UNSIGNED NULL, service_id BIGINT UNSIGNED NULL, payment_type ENUM('ONE_TIME','SUBSCRIPTION') NOT NULL, amount_cents INT UNSIGNED NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'BRL', description VARCHAR(255) NULL, expires_at DATETIME NULL, max_uses INT UNSIGNED NULL, uses_count INT UNSIGNED NOT NULL DEFAULT 0, status ENUM('ACTIVE','USED','EXPIRED','CANCELED') NOT NULL DEFAULT 'ACTIVE', created_by VARCHAR(190) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(plan_id) REFERENCES plans(id), FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(service_id) REFERENCES services(id)) ENGINE=InnoDB;
CREATE TABLE payment_intents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(26) NOT NULL UNIQUE, idempotency_key VARCHAR(190) NOT NULL UNIQUE, service_id BIGINT UNSIGNED NULL, customer_id BIGINT UNSIGNED NOT NULL, plan_id BIGINT UNSIGNED NULL, payment_link_id BIGINT UNSIGNED NULL, type ENUM('ONE_TIME','SUBSCRIPTION') NOT NULL, amount_cents INT UNSIGNED NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'PENDING', gateway VARCHAR(40) NOT NULL DEFAULT 'asaas', gateway_id VARCHAR(100) NULL, checkout_url VARCHAR(500) NULL, metadata JSON NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(service_id) REFERENCES services(id), FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(plan_id) REFERENCES plans(id), FOREIGN KEY(payment_link_id) REFERENCES payment_links(id), INDEX(gateway_id), INDEX(status)) ENGINE=InnoDB;
CREATE TABLE webhook_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, gateway VARCHAR(40) NOT NULL, event_id VARCHAR(190) NOT NULL, event_name VARCHAR(100) NOT NULL, payload JSON NOT NULL, processed_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_gateway_event(gateway,event_id)) ENGINE=InnoDB;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor VARCHAR(190) NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(80) NULL, entity_id BIGINT UNSIGNED NULL, ip_address VARCHAR(45) NULL, details JSON NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;

